interactions.sample_code:
function insertionSort() {
  for (let j = 2; j <= 6; j++) {
    get_key(j);
    let i = j - 1;
    while (i >= 1 && compare_with_key(i)) {
      shift(i);
      i = i - 1;
    }
    insert(i + 1);
  }
}

